\node[below,font=\scriptsize] at (10.75,0) {Cycle};
\node[rotate=90] at (-1.4,4.5) {Number of students};
\node[below] at (6.15,-1.0) {Travel method};
\node at (6.15,10.1) {How Year 9 travel};
